// [MEDIUM_PRIORITY] VALIDATION: String conversion safety
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.sttimport android.content.Contextimport android.content.Intentimport android.os.Bundleimport android.speech.RecognitionListenerimport android.speech.RecognizerIntentimport android.speech.SpeechRecognizerimport com.roshan.persona.voice.capture.AudioCapturePipelineimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport kotlinx.coroutines.Jobimport kotlinx.coroutines.channels.awaitCloseimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.flow.callbackFlowimport kotlinx.coroutines.flow.flowimport kotlinx.coroutines.supervisorScopeimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Android Speech Recognizer STT Engine (Module 5, Tier 1 — Cloud STT). * * Strategy §5.3: "Cloud STT (Android SpeechRecognizer) — Tier 1, best accuracy" * * Uses Android's built-in [SpeechRecognizer] which delegates to the system's * cloud speech recognition service (Google Cloud Speech on most devices). * This is the highest-accuracy STT tier — when available, it's preferred over * offline Whisper (Tier 2) and Vosk (Tier 3). * * ## How it works * * 1. [recognize] starts a [SpeechRecognizer] session with streaming results. * 2. The [RecognitionListener] receives partial + final results. * 3. Each partial result is emitted as [SttResult.Partial]. * 4. The final result is emitted as [SttResult.Final]. * 5. On error, [SttResult.Error] is emitted with the appropriate reason. * * ## Availability * * [SpeechRecognizer.isRecognitionAvailable] checks if the service exists. * On devices without Google Play Services (AOSP-only), this returns false * and the [StreamingSttEngine] falls back to offline Whisper. * * ## Privacy * * Android's SpeechRecognizer sends audio to the cloud (Google's servers). * Strategy §5.3: "Cloud STT is tried first (and falls back gracefully on * network errors)." The user can disable cloud STT in Privacy Settings * (handled by [StreamingSttEngine] via [NetworkProbe] + privacy flag). * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§5.3 Speech-to-Text — Hybrid Cloud + Offline</a> */@Singletonclass AndroidSpeechRecognizerEngine @Inject constructor(    private val context: Context,) : CloudSttEngine {    @Volatile    private var recognizer: SpeechRecognizer? = null    @Volatile    private var isCancelled: Boolean = false    override suspend fun recognize(        audioStream: Flow<AudioCapturePipeline.AudioChunk>,        confidenceScorer: SttConfidenceScorer,    ): Flow<SttResult> = callbackFlow {        // Check availability.        if (!SpeechRecognizer.isRecognitionAvailable(context)) {            trySend(SttResult.Error(                reason = SttResult.Error.Reason.UNKNOWN,                message = "SpeechRecognizer not available on this device",            ))            close()            return@callbackFlow        }        isCancelled = false        var accumulatedText = StringBuilder()        // Create the recognizer. SpeechRecognizer MUST be created on the main        // thread — otherwise it throws RuntimeException. We use withContext to        // ensure main-thread creation even if recognize() is called from IO.        val speechRecognizer = withContext(Dispatchers.Main) {            SpeechRecognizer.createSpeechRecognizer(context)        }        recognizer = speechRecognizer        // Build the recognition intent.        val recognizerIntent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {            putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)            putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS, true)            putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 1)            // Request streaming partial results.            putExtra("android.speech.extra.DICTATION_MODE", true)        }        // Set up the recognition listener.        speechRecognizer.setRecognitionListener(object : RecognitionListener {            override fun onReadyForSpeech(params: Bundle?) {                Timber.d("SpeechRecognizer ready for speech")            }            override fun onBeginningOfSpeech() {                Timber.d("SpeechRecognizer: beginning of speech")            }            override fun onRmsChanged(rmsdB: Float) {                // RMS level change — not used for results, but available for UI waveform.            }            override fun onBufferReceived(buffer: ByteArray?) {                // Raw audio buffer — not used (we use the recognized text instead).            }            override fun onEndOfSpeech() {                Timber.d("SpeechRecognizer: end of speech")            }            override fun onError(error: Int) {                val reason = when (error) {                    SpeechRecognizer.ERROR_NETWORK -> SttResult.Error.Reason.NETWORK_DROPPED                    SpeechRecognizer.ERROR_NETWORK_TIMEOUT -> SttResult.Error.Reason.NETWORK_DROPPED                    SpeechRecognizer.ERROR_AUDIO -> SttResult.Error.Reason.AUDIO_DEVICE                    SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS -> SttResult.Error.Reason.MIC_PERMISSION                    else -> SttResult.Error.Reason.UNKNOWN                }                val message = when (error) {                    SpeechRecognizer.ERROR_NETWORK -> "Network error during cloud STT"                    SpeechRecognizer.ERROR_NETWORK_TIMEOUT -> "Network timeout during cloud STT"                    SpeechRecognizer.ERROR_AUDIO -> "Audio recording error"                    SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS -> "Microphone permission denied"                    SpeechRecognizer.ERROR_CLIENT -> "Client-side error"                    SpeechRecognizer.ERROR_SERVER -> "Server-side error"                    SpeechRecognizer.ERROR_NO_MATCH -> "No speech matched"                    SpeechRecognizer.ERROR_RECOGNIZER_BUSY -> "Recognizer busy"                    SpeechRecognizer.ERROR_SPEECH_TIMEOUT -> "No speech detected (timeout)"                    else -> "Unknown error (code=$error)"                }                Timber.w("SpeechRecognizer error: %s (code=%d)", message, error)                trySend(SttResult.Error(                    reason = reason,                    message = message,                ))                close()            }            override fun onResults(results: Bundle?) {                val matches = results?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)                val confidences = results?.getFloatArray(SpeechRecognizer.CONFIDENCE_SCORES)                val text = matches?.firstOrNull() ?: ""                val confidence = confidences?.firstOrNull() ?: 0.8f                if (text.isNotEmpty()) {                    trySend(SttResult.Final(                        text = text,                        language = java.util.Locale.getDefault().language,                        confidence = confidence.coerceIn(0f, 1f),                    ))                }                close()            }            override fun onPartialResults(partialResults: Bundle?) {                val matches = partialResults?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)                val text = matches?.firstOrNull() ?: ""                if (text.isNotEmpty() && text != accumulatedText.toString()) {                    accumulatedText = StringBuilder(text)                    trySend(SttResult.Partial(                        text = text,                        language = java.util.Locale.getDefault().language,                        confidence = 0.7f,  // partial results don't have confidence                    ))                }            }            override fun onEvent(eventType: Int, params: Bundle?) {                Timber.d("SpeechRecognizer event: %d", eventType)            }        })        // Start listening. Note: SpeechRecognizer uses the device microphone directly,        // not the audioStream parameter. The audioStream is used by the offline engine        // (Whisper) which processes audio chunks via JNI. For cloud STT, we start        // listening and emit results as they come.        speechRecognizer.startListening(recognizerIntent)        // Wait for cancellation.        awaitClose {            if (!isCancelled) {                speechRecognizer.stopListening()            }            speechRecognizer.destroy()            recognizer = null        }    }    override suspend fun cancel() {        isCancelled = true        recognizer?.stopListening()        recognizer?.destroy()        recognizer = null    }}